		readiness.Message = "Admin audit log 计数存在，但导出查询样本回读为空，不能确认过滤条件可用。"
		readiness.Recovery = "先核对 admin_audit_log 列表回读和分页权限；不得通过写入新审计记录来掩盖查询样本问题。"
