	taskPreflightReady := activationAuditEventCount > 0 &&
		querySampleCount > 0 &&
		supportedFilterFieldCount >= enterpriseAuditExportQueryRequiredFilterFieldCount &&
		retentionPolicyConfigured &&
		retentionPolicyValid
	coveredSourceCount := 0
