		readiness.Message = "Admin audit log 尚无可供交付报告存储契约使用的真源。"
		readiness.Recovery = "先通过受控 Admin 操作形成 admin_audit_log 真源；当前 readiness 不写 report storage 或 audit。"
		return readiness, nil
